INSERT INTO `fingering_charts` (`id`, `instrument_id`, `pitch_id`, `image_url`, `description`, `created_at`, `updated_at`, `pattern_json`) VALUES (1,1,27,NULL,NULL,'2026-11-03 06:25:14.190919','2026-11-03 06:25:14.190919','{\"blow\": \"MID\", \"name\": \"협종\", \"basic\": false, \"hanja\": \"夾\", \"holes\": [\"CLOSED\", \"CLOSED\", \"CLOSED\", \"CLOSED\", \"CLOSED\"], \"source\": \"출처: 국립국악원 e국악아카데미 「단소 안공법」. 높은 태는 제1공(뒷구멍)과 제3공을 막아요.\", \"reading\": \"협\", \"instrumentNote\": \"뒷구멍은 왼손 엄지로 막아요. 역취는 입김을 세게 불어요. 높은 태(청태)는 낮은 태와 운지가 달라요.\", \"verificationStatus\": \"BUILTIN_REFERENCE\", \"nominalHwangPitchClass\": 3}');
