INSERT INTO `reference_audio_assets` (`asset_id`, `dataset_id`, `label_id`, `category`, `technique`, `register_name`, `yulmyeong`, `display_label`, `object_key`, `content_type`, `sha256`, `byte_size`, `duration_ms`, `sample_rate_hz`, `channels`, `review_status`, `eligible_for_note_scoring`, `metadata_json`, `pitch_id`, `pitch_mapping_basis`, `status`, `created_at`, `updated_at`) VALUES ('92ce29de495a35b2fc470abec83dbaadc6b91d5d6d9cd7379a757a0e68774db8','danso','ngc-danso-2350.gesture-001','시김새','니','역취','임','역취 임','reference-audio/v1/danso/92ce29de495a35b2fc470abec83dbaadc6b91d5d6d9cd7379a757a0e68774db8/cfb8f7298d1496220ad67d682234d9941a76ce247f5ab7d16bba3753e5b5bfe8.m4a','audio/mp4','cfb8f7298d1496220ad67d682234d9941a76ce247f5ab7d16bba3753e5b5bfe8',58925,2653,44100,1,'inferred',0,'{\"wav\": {\"bytes\": 234028, \"frames\": 116992, \"sha256\": \"14c138703552115c2464354b3ace3490c7fc1365fdf07e3bcff84054ebefd281\", \"channels\": 1, \"sampleRateHz\": 44100}, \"label\": {\"id\": \"ngc-danso-2350.gesture-001\", \"file\": \"시김새/니/001_역취_임.wav\", \"gain\": 1.0, \"bytes\": 234028, \"format\": \"WAV_PCM16\", \"frames\": 116992, \"method\": \"tool:prepare_danso_assets@ac0e383e5335\", \"review\": \"inferred\", \"sha256\": \"14c138703552115c2464354b3ace3490c7fc1365fdf07e3bcff84054ebefd281\", \"category\": \"시김새\", \"channels\": 1, \"evidence\": {\"labelF0Hz\": 893.027, \"analysisBasis\": \"같은 단소의 평취/역취 5음 배열, 황종 명시 요성(2343), 시김새의 상대 음이동 설명과 실제 안정음/스펙트럼을 대조. https://korean.go.kr/common/download.do?c_file_name=korean_music_finger_alphabet.pdf&file_path=about&o_file_name=%ED%95%9C%EA%B5%AD+%EC%9D%8C%EC%95%85+%EC%A0%90%EC%9E%90+%EA%B7%9C%EC%A0%95+%ED%95%B4%EC%84%A4%EC%84%9C.pdf 본음 주변 이동이므로 파일 전체 F0 중앙값으로 하나의 음을 확정하지 않는다. 각 행은 마지막 안정음; 전체 순서는 evidence.sequenceDecision. 관측 음고를 보존하고 튜닝/옥타브 자동 보정 없음.\", \"boundaryReview\": {\"observedF0Hz\": [397.5, 405.4], \"windowSeconds\": [0.19, 0.28], \"interpretation\": \"취음 직후 역취 중의 아래 옥타브 성분이 잠깐 나타난다. 독립 발음으로 나누지 않고 전체 클립에 보존한다.\"}, \"repeatAssessment\": \"무음으로 분리된 반복 발음 없음. 시김새 내부 이동과 약한 취음은 같은 원음 구간에 유지.\", \"sequenceDecision\": {\"timeUnit\": \"absolute_seconds_in_source\", \"labelMeaning\": \"마지막 안정음. 앞선 주음과 모든 내부 이동은 orderedAnchors로 보존하며 독립 발음으로 분리하지 않는다.\", \"spectralCheck\": \"각 선택창 중심의 Hann FFT에서 YIN F0 주변 피크를 대조. 짧은 경유음의 창은4096샘플보다 짧아 인접음 영향이 남을 수 있다.\", \"orderedAnchors\": [{\"f0Hz\": 814.942, \"p10Hz\": 813.101, \"p90Hz\": 816.429, \"register\": \"역취\", \"yulmyeong\": \"중\", \"validFrames\": 180, \"windowsSeconds\": [[0.4, 2.2]], \"spectralPeakNearF0Hz\": 816.916}, {\"f0Hz\": 893.027, \"p10Hz\": 892.232, \"p90Hz\": 893.5, \"register\": \"역취\", \"yulmyeong\": \"임\", \"validFrames\": 28, \"windowsSeconds\": [[2.4, 2.68]], \"spectralPeakNearF0Hz\": 892.45}], \"labelAnchorIndex\": 1}}, \"register\": \"역취\", \"sourceId\": \"ngc-danso-2350\", \"technique\": \"니\", \"yulmyeong\": \"임\", \"endSeconds\": 2.80288, \"processing\": \"channel mean; attenuation only above 0.999; PCM16; no resampling/pitch correction\", \"displayLabel\": \"역취 임\", \"sampleRateHz\": 44100, \"startSeconds\": 0.15, \"sourceStartFrame\": 6615, \"eligibleForNoteScoring\": false, \"sourceEndFrameExclusive\": 123607}, \"source\": {\"id\": \"ngc-danso-2350\", \"kind\": \"audio\", \"bytes\": 720732, \"title\": \"니\", \"sha256\": \"31ce785c1139707316181af02108aeb8848422be260e5cbb908cd660d698bf8e\", \"license\": \"KOGL-1\", \"rawPath\": \"data/raw/instruments/danso/Danso_13.wav\", \"category\": \"시김새\", \"channels\": 2, \"publisher\": \"국립국악원\", \"sourceUrl\": \"https://www.gugak.go.kr/digitaleum/front/monotone/list.do\", \"verifiedOn\": \"2026-10-23\", \"attribution\": \"국립국악원, 국악기 디지털 음원, 단소, 니, mntn_seq=2350, 공공누리 제1유형(출처표시)\", \"downloadUrl\": \"https://www.gugak.go.kr/digitaleum/cmmn/file/monotone/download.do\", \"sampleRateHz\": 44100, \"sourceItemId\": 2350, \"annotationPath\": \"data/annotations/audio/danso/ngc-danso-2350-니/labels.json\", \"instrumentCode\": 19860, \"redistribution\": {\"adapted\": \"possible_with_conditions\", \"