INSERT INTO `reference_audio_assets` (`asset_id`, `dataset_id`, `label_id`, `category`, `technique`, `register_name`, `yulmyeong`, `display_label`, `object_key`, `content_type`, `sha256`, `byte_size`, `duration_ms`, `sample_rate_hz`, `channels`, `review_status`, `eligible_for_note_scoring`, `metadata_json`, `pitch_id`, `pitch_mapping_basis`, `status`, `created_at`, `updated_at`) VALUES ('f71dedcc55fc38f92bc332f0be60fad4a551ac5aecc4789c16cc7be13e18ca73','danso','ngc-danso-2361.gesture-001','시김새','노네','평취','태','평취 태','reference-audio/v1/danso/f71dedcc55fc38f92bc332f0be60fad4a551ac5aecc4789c16cc7be13e18ca73/67500e462d4b0f8855d04c63974cdd7d67f5efd09bc6ee384f5bbf710f7b1d12.m4a','audio/mp4','67500e462d4b0f8855d04c63974cdd7d67f5efd09bc6ee384f5bbf710f7b1d12',65889,2573,44100,1,'inferred',0,'{\"wav\": {\"bytes\": 226972, \"frames\": 113464, \"sha256\": \"3b7fa82b8325bf847b73b7e02be6bea8a5dbe3284ccfb2d506fd5811dbc375f0\", \"channels\": 1, \"sampleRateHz\": 44100}, \"label\": {\"id\": \"ngc-danso-2361.gesture-001\", \"file\": \"시김새/노네/001_평취_태.wav\", \"gain\": 1.0, \"bytes\": 226972, \"format\": \"WAV_PCM16\", \"frames\": 113464, \"method\": \"tool:prepare_danso_assets@ac0e383e5335\", \"review\": \"inferred\", \"sha256\": \"3b7fa82b8325bf847b73b7e02be6bea8a5dbe3284ccfb2d506fd5811dbc375f0\", \"category\": \"시김새\", \"channels\": 1, \"evidence\": {\"labelF0Hz\": 673.123, \"analysisBasis\": \"같은 단소의 평취/역취 5음 배열, 황종 명시 요성(2343), 시김새의 상대 음이동 설명과 실제 안정음/스펙트럼을 대조. https://korean.go.kr/common/download.do?c_file_name=korean_music_finger_alphabet.pdf&file_path=about&o_file_name=%ED%95%9C%EA%B5%AD+%EC%9D%8C%EC%95%85+%EC%A0%90%EC%9E%90+%EA%B7%9C%EC%A0%95+%ED%95%B4%EC%84%A4%EC%84%9C.pdf 본음 주변 이동이므로 파일 전체 F0 중앙값으로 하나의 음을 확정하지 않는다. 각 행은 마지막 안정음; 전체 순서는 evidence.sequenceDecision. 관측 음고를 보존하고 튜닝/옥타브 자동 보정 없음.\", \"repeatAssessment\": \"무음으로 분리된 반복 발음 없음. 시김새 내부 이동과 약한 취음은 같은 원음 구간에 유지.\", \"sequenceDecision\": {\"timeUnit\": \"absolute_seconds_in_source\", \"labelMeaning\": \"마지막 안정음. 앞선 주음과 모든