INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (1,'DANSO',1,'악기 알기·감상','READ',0,'{\"why\": \"지도서는 악기를 보고 모범 연주를 먼저 듣는 범주 학습을 가장 앞에 둬요.\", \"goal\": \"소리와 악기 구조를 안다\", \"parts\": [\"취구(U자 홈)\", \"뒷구멍 1개 · 왼손 엄지\", \"앞 지공 4개\"], \"songs\": [], \"tasks\": [{\"title\": \"악기 구조와 이름 보기\", \"description\": \"취구·지공 같은 부분 이름을 알아 둬요.\"}, {\"title\": \"모범 연주 듣기\", \"description\": \"이 악기로 연주한 소리를 듣고 높낮이·음색을 귀로 익혀요.\"}], \"ranges\": [], \"source\": \"단소 지도서 기본원칙 ①·④, 과정안 기초단계 1·2항. 모든 강좌의 1차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": null}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-10 05:33:39.757705');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (2,'DANSO',2,'자세·호흡','READ',0,'{\"why\": \"지도서 연주법 장의 순서(자세 → 안공법 → 발음법 → 호흡법)를 따라요.\", \"goal\": \"바르게 잡고 숨을 고르게 쓴다\", \"parts\": [], \"songs\": [], \"tasks\": [{\"title\": \"앉은 자세\", \"description\": \"허리를 펴고 어깨 힘을 빼요.\"}, {\"title\": \"악기 잡기\", \"description\": \"세로로 세워 잡아요. 뒷구멍은 왼손 엄지, 앞 위 두 구멍은 왼손 검지·중지, 셋째 구멍은 오른손 중지로 막아요.\"}, {\"title\": \"복식호흡\", \"description\": \"배로 숨을 들이쉬고 길고 고르게 내쉬어요.\"}], \"ranges\": [], \"source\": \"단소 지도서 연주법 장. 소금 교실 2·3차시, 대금 기초편 8차시, 단소 교실 2차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": null}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-16 15:43:46.473190');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (3,'DANSO',3,'첫 소리','PITCH',0,'{\"why\": \"첫 소리는 음높이보다 소리가 끊기지 않고 고르게 나는지가 중요해요.\", \"goal\": \"안정된 소리 하나를 낸다\", \"parts\": [], \"songs\": [], \"tasks\": [{\"title\": \"취구에 입술 대기\", \"description\": \"입술을 옆으로 펴 아랫입술에 취구를 대요.\"}, {\"title\": \"입김 방향·세기 찾기\", \"description\": \"\'휘\' 하듯 약하게, 반은 취구 안으로 불어요.\"}, {\"title\": \"한 소리 길게 내기\", \"description\": \"같은 소리를 끊지 않고 이어 봐요.\"}], \"ranges\": [], \"source\": \"단소 지도서 발음법 1·2항, 대금 기초편 7차시\", \"pitchNote\": null, \"pitchNames\": [\"汰\"], \"passCriteria\": {\"title\": \"한 소리를 2초 이상 끊김 없이 3번\", \"description\": \"음높이는 묻지 않고 소리가 났는지·흔들림만 봐요.\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-16 15:43:46.548197');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (4,'DANSO',4,'기본음','PITCH',0,'{\"why\": \"소리 내기 쉬운 음부터 배워요. 율명 구음을 소리 내어 읽으며 함께 익혀요.\", \"goal\": \"쉬운 음부터 율명과 운지를 익힌다\", \"parts\": [], \"songs\": [], \"tasks\": [], \"ranges\": [], \"source\": \"단소 지도서 발음법 3항, 소금 교실 5~7차시, 대금 교실 2~4차시\", \"pitchNote\": {\"text\": \"구멍을 다 연 汰(태)부터 하나씩 막으며 내려가요. 仲·林 같은 낮은 음은 어려워서 뒤에 해요. 반음 夾·南은 다섯 음이 익은 뒤에 배워요.\", \"caution\": \"정일영(2014)은 汰와 같은 입김으로 나는 가운데 소리를 먼저 익히자고 하고, 단소 교실은 낮은 소리 → 높은 소리 순이라 자료마다 첫 음이 달라요.\"}, \"pitchNames\": [\"汰\", \"潢\", \"無\", \"林\", \"仲\"], \"passCriteria\": {\"title\": \"음마다 2초 이상 유지\", \"description\": \"목표 음과 ±25센트 이내면 통과(예시).\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (5,'DANSO',5,'음 잇기','PITCH',0,'{\"why\": \"기본음이 되면 순차 진행 → 건너뛰기 → 세 음 동요 순서로 넓혀요.\", \"goal\": \"이웃 음과 건너뛴 음을 이어 분다\", \"parts\": [], \"songs\": [], \"tasks\": [], \"ranges\": [], \"source\": \"단소 지도서 발음법 3항·과정안 발전단계, 소금 교실 5차시(3음 동요)\", \"pitchNote\": null, \"pitchNames\": [\"仲\", \"林\", \"無\", \"潢\", \"汰\"], \"passCriteria\": {\"title\": \"패턴의 8음 중 7음 이상 맞음\", \"description\": \"음 사이 끊김은 박으로 세지 않아요(예시).\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (6,'DANSO',6,'음역 넓히기','PITCH',0,'{\"why\": \"같은 운지에서 입김 세기로 옥타브를 바꾸는 연습이에요.\", \"goal\": \"높은·낮은 음역을 낸다\", \"parts\": [], \"songs\": [], \"tasks\": [], \"ranges\": [{\"blow\": \"HIGH\", \"label\": \"역취 · 한 옥타브 위\", \"firstPitch\": \"㳞\", \"description\": \"평취와 같은 운지에 입김을 세게 불어요.\"}], \"source\": \"단소 지도서 발음법 4·5항, 대금 교실 5~7차시, 대금 기초편 10~13차시, 소금 교실 13차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": {\"title\": \"새 음역의 음을 각각 2초 이상 유지\", \"description\": \"평취 음과 옥타브 차이가 나는지 봐요(예시).\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (7,'DANSO',7,'혀치기','BEAT',0,'{\"why\": \"같은 음을 여러 번 낼 때 숨은 그대로 두고 혀로 끊어요. 정간 안 박 나누기는 정간보 쉽게 읽기에서 봐요.\", \"goal\": \"같은 음을 혀로 끊어 반복한다\", \"parts\": [], \"songs\": [], \"tasks\": [{\"title\": \"혀치기\", \"description\": \"같은 음을 \\\"투·투·투\\\" 혀로 끊어 4번 반복해요.\"}], \"ranges\": [], \"source\": \"단소 지도서 발음법 6항, 소금 교실 8차시, 대금 기초편 14~18차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": {\"title\": \"혀치기 4번 반복, 박 어긋남 ±15% 이내\", \"description\": \"같은 음을 고르게 끊어 내는지 봐요(예시).\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-10 05:33:39.772090');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (8,'DANSO',8,'악보와 곡','BEAT',0,'{\"why\": \"지도서는 평취로 된 쉬운 곡부터, 정간보로 먼저 가르친 뒤 오선보를 보게 해요. 장단 반주를 함께 틀어요.\", \"goal\": \"정간보를 보고 장단에 맞춰 곡을 분다\", \"parts\": [], \"songs\": [{\"meta\": \"3음 · 평취\", \"title\": \"비행기\"}, {\"meta\": \"평취\", \"title\": \"새야새야\"}, {\"meta\": \"세마치장단\", \"title\": \"아리랑\"}, {\"meta\": \"세마치장단\", \"title\": \"도라지타령\"}, {\"meta\": \"굿거리장단\", \"title\": \"천안삼거리\"}, {\"meta\": \"굿거리장단\", \"title\": \"풍년가\"}], \"tasks\": [{\"title\": \"정간보 읽는 순서 확인\", \"description\": \"위에서 아래로, 오른쪽에서 왼쪽으로.\"}, {\"title\": \"율명 보며 천천히 불기\", \"description\": \"한 각씩 끊어 연습해요.\"}, {\"title\": \"장단 반주에 맞춰 곡 전체 불기\", \"description\": \"연습곡 화면에서 속도를 낮춰 시작해요.\"}], \"ranges\": [], \"source\": \"단소 지도서 과정안 통합단계·기본원칙 ⑧, 대금 교실 8~10차시, 소금 교실 9·10차시\", \"pitchNote\": null, \"pitchNames\": [\"仲\", \"林\", \"無\", \"潢\", \"汰\"], \"passCriteria\": {\"title\": \"곡 전체 음정·박자 각 70점 이상\", \"description\": \"AI 연주 평가 결과 화면의 점수를 그대로 써요(예시).\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (9,'DANSO',9,'장식음·시김새','LISTEN',1,'{\"why\": \"모든 자료가 마지막 단계로 둬요. 지도서는 잘 되지 않으면 무리하게 지도하지 않고 감상으로 소개하는 선에서 끝내도 된다고 해요. 그래서 판정 없이 듣고 따라 해요.\", \"goal\": \"꾸밈음과 요성·퇴성을 맛본다\", \"parts\": [], \"songs\": [], \"tasks\": [{\"title\": \"앞·뒤 꾸밈음 듣고 따라 하기\", \"description\": null}, {\"title\": \"굴리기\", \"description\": null}, {\"title\": \"요성(떠는 소리)·퇴성(흘러내리는 소리)\", \"description\": \"모범 연주를 듣고 흉내 내 봐요.\"}], \"ranges\": [], \"source\": \"단소 지도서 과정안 심화단계·발음법 8항, 소금 교실 11·14차시, 대금 교실 12·13차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": null}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (10,'SOGEUM',1,'악기 알기·감상','READ',0,'{\"why\": \"지도서는 악기를 보고 모범 연주를 먼저 듣는 범주 학습을 가장 앞에 둬요.\", \"goal\": \"소리와 악기 구조를 안다\", \"parts\": [\"취구\", \"지공 6개\"], \"songs\": [], \"tasks\": [{\"title\": \"악기 구조와 이름 보기\", \"description\": \"취구·지공 같은 부분 이름을 알아 둬요.\"}, {\"title\": \"모범 연주 듣기\", \"description\": \"이 악기로 연주한 소리를 듣고 높낮이·음색을 귀로 익혀요.\"}], \"ranges\": [], \"source\": \"단소 지도서 기본원칙 ①·④, 과정안 기초단계 1·2항. 모든 강좌의 1차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": null}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-10 05:33:39.757705');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (11,'SOGEUM',2,'자세·호흡','READ',0,'{\"why\": \"지도서 연주법 장의 순서(자세 → 안공법 → 발음법 → 호흡법)를 따라요.\", \"goal\": \"바르게 잡고 숨을 고르게 쓴다\", \"parts\": [], \"songs\": [], \"tasks\": [{\"title\": \"앉은 자세\", \"description\": \"허리를 펴고 어깨 힘을 빼요.\"}, {\"title\": \"악기 잡기\", \"description\": \"가로로 오른쪽을 향해 잡아요. 왼손이 취구 쪽 세 구멍, 오른손이 아래 세 구멍을 막아요.\"}, {\"title\": \"복식호흡\", \"description\": \"배로 숨을 들이쉬고 길고 고르게 내쉬어요.\"}], \"ranges\": [], \"source\": \"단소 지도서 연주법 장. 소금 교실 2·3차시, 대금 기초편 8차시, 단소 교실 2차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": null}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (12,'SOGEUM',3,'첫 소리','PITCH',0,'{\"why\": \"첫 소리는 음높이보다 소리가 끊기지 않고 고르게 나는지가 중요해요.\", \"goal\": \"안정된 소리 하나를 낸다\", \"parts\": [], \"songs\": [], \"tasks\": [{\"title\": \"취구에 입술 대기\", \"description\": \"아랫입술을 펴고 취구를 입술 가운데 대요.\"}, {\"title\": \"입김 방향·세기 찾기\", \"description\": \"\'휘\' 하듯 약하게, 반은 취구 안으로 불어요.\"}, {\"title\": \"한 소리 길게 내기\", \"description\": \"같은 소리를 끊지 않고 이어 봐요.\"}], \"ranges\": [], \"source\": \"단소 지도서 발음법 1·2항, 대금 기초편 7차시\", \"pitchNote\": null, \"pitchNames\": [\"㴌\"], \"passCriteria\": {\"title\": \"한 소리를 2초 이상 끊김 없이 3번\", \"description\": \"음높이는 묻지 않고 소리가 났는지·흔들림만 봐요.\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-16 15:43:46.548197');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (13,'SOGEUM',4,'기본음','PITCH',0,'{\"why\": \"소리 내기 쉬운 음부터 배워요. 율명 구음을 소리 내어 읽으며 함께 익혀요.\", \"goal\": \"쉬운 음부터 율명과 운지를 익힌다\", \"parts\": [], \"songs\": [], \"tasks\": [], \"ranges\": [], \"source\": \"단소 지도서 발음법 3항, 소금 교실 5~7차시, 대금 교실 2~4차시\", \"pitchNote\": {\"text\": \"고·태·황 → 무·남·임 → 중 순서예요(소금 교실 5~7차시). 역취 황은 6단계에서 해요.\", \"caution\": null}, \"pitchNames\": [\"㴌\", \"汰\", \"潢\", \"無\", \"南\", \"林\", \"㳞\"], \"passCriteria\": {\"title\": \"음마다 2초 이상 유지\", \"description\": \"목표 음과 ±25센트 이내면 통과(예시).\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
