INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (18,'SOGEUM',9,'장식음·시김새','LISTEN',1,'{\"why\": \"모든 자료가 마지막 단계로 둬요. 지도서는 잘 되지 않으면 무리하게 지도하지 않고 감상으로 소개하는 선에서 끝내도 된다고 해요. 그래서 판정 없이 듣고 따라 해요.\", \"goal\": \"꾸밈음과 요성·퇴성을 맛본다\", \"parts\": [], \"songs\": [], \"tasks\": [{\"title\": \"앞·뒤 꾸밈음 듣고 따라 하기\", \"description\": null}, {\"title\": \"굴리기\", \"description\": null}, {\"title\": \"요성(떠는 소리)·퇴성(흘러내리는 소리)\", \"description\": \"모범 연주를 듣고 흉내 내 봐요.\"}], \"ranges\": [], \"source\": \"단소 지도서 과정안 심화단계·발음법 8항, 소금 교실 11·14차시, 대금 교실 12·13차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": null}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (19,'DAEGEUM_JEONGAK',1,'악기 알기·감상','READ',0,'{\"why\": \"지도서는 악기를 보고 모범 연주를 먼저 듣는 범주 학습을 가장 앞에 둬요.\", \"goal\": \"소리와 악기 구조를 안다\", \"parts\": [\"취구\", \"청공(갈대 속청)\", \"지공 6개\", \"칠성공\"], \"songs\": [], \"tasks\": [{\"title\": \"악기 구조와 이름 보기\", \"description\": \"취구·지공 같은 부분 이름을 알아 둬요.\"}, {\"title\": \"모범 연주 듣기\", \"description\": \"이 악기로 연주한 소리를 듣고 높낮이·음색을 귀로 익혀요.\"}], \"ranges\": [], \"source\": \"단소 지도서 기본원칙 ①·④, 과정안 기초단계 1·2항. 모든 강좌의 1차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": null}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-10 05:33:39.757705');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (20,'DAEGEUM_JEONGAK',2,'자세·호흡','READ',0,'{\"why\": \"지도서 연주법 장의 순서(자세 → 안공법 → 발음법 → 호흡법)를 따라요.\", \"goal\": \"바르게 잡고 숨을 고르게 쓴다\", \"parts\": [], \"songs\": [], \"tasks\": [{\"title\": \"앉은 자세\", \"description\": \"허리를 펴고 어깨 힘을 빼요.\"}, {\"title\": \"악기 잡기\", \"description\": \"왼쪽 어깨에 걸쳐 가로로 잡아요. 왼손이 취구 쪽 세 구멍, 오른손이 아래 세 구멍을 막아요.\"}, {\"title\": \"복식호흡\", \"description\": \"배로 숨을 들이쉬고 길고 고르게 내쉬어요.\"}], \"ranges\": [], \"source\": \"단소 지도서 연주법 장. 소금 교실 2·3차시, 대금 기초편 8차시, 단소 교실 2차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": null}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-16 15:43:46.479616');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (21,'DAEGEUM_JEONGAK',3,'첫 소리','PITCH',0,'{\"why\": \"첫 소리는 음높이보다 소리가 끊기지 않고 고르게 나는지가 중요해요.\", \"goal\": \"안정된 소리 하나를 낸다\", \"parts\": [], \"songs\": [], \"tasks\": [{\"title\": \"취구에 입술 대기\", \"description\": \"아랫입술을 펴고 취구를 입술 가운데 대요.\"}, {\"title\": \"입김 방향·세기 찾기\", \"description\": \"입김을 가늘게 모아 약하게 불어요.\"}, {\"title\": \"한 소리 길게 내기\", \"description\": \"같은 소리를 끊지 않고 이어 봐요.\"}], \"ranges\": [], \"source\": \"단소 지도서 발음법 1·2항, 대금 기초편 7차시\", \"pitchNote\": null, \"pitchNames\": [\"㳞\"], \"passCriteria\": {\"title\": \"한 소리를 2초 이상 끊김 없이 3번\", \"description\": \"음높이는 묻지 않고 소리가 났는지·흔들림만 봐요.\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-16 15:43:46.551010');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (22,'DAEGEUM_JEONGAK',4,'기본음','PITCH',0,'{\"why\": \"소리 내기 쉬운 음부터 배워요. 율명 구음을 소리 내어 읽으며 함께 익혀요.\", \"goal\": \"쉬운 음부터 율명과 운지를 익힌다\", \"parts\": [], \"songs\": [], \"tasks\": [], \"ranges\": [], \"source\": \"단소 지도서 발음법 3항, 소금 교실 5~7차시, 대금 교실 2~4차시\", \"pitchNote\": {\"text\": \"지공을 모두 연 음 → 평취 왼손 음 → 평취 오른손 음 순서예요(대금 교실 2~4차시).\", \"caution\": \"강좌는 차시 제목만 확인해서 \\\"모든 지공을 연 음\\\"이 어느 율명인지는 확인이 필요해요. 대금 기초편은 중간 → 높은 → 낮은 음역 순이에요.\"}, \"pitchNames\": [\"㳞\", \"汰\", \"潢\", \"南\", \"林\"], \"passCriteria\": {\"title\": \"음마다 2초 이상 유지\", \"description\": \"목표 음과 ±25센트 이내면 통과(예시).\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (23,'DAEGEUM_JEONGAK',5,'음 잇기','PITCH',0,'{\"why\": \"기본음이 되면 순차 진행 → 건너뛰기 → 세 음 동요 순서로 넓혀요.\", \"goal\": \"이웃 음과 건너뛴 음을 이어 분다\", \"parts\": [], \"songs\": [], \"tasks\": [], \"ranges\": [], \"source\": \"단소 지도서 발음법 3항·과정안 발전단계, 소금 교실 5차시(3음 동요)\", \"pitchNote\": null, \"pitchNames\": [\"林\", \"南\", \"潢\", \"汰\", \"㳞\"], \"passCriteria\": {\"title\": \"패턴의 8음 중 7음 이상 맞음\", \"description\": \"음 사이 끊김은 박으로 세지 않아요(예시).\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (24,'DAEGEUM_JEONGAK',6,'음역 넓히기','PITCH',0,'{\"why\": \"같은 운지에서 입김 세기로 옥타브를 바꾸는 연습이에요.\", \"goal\": \"높은·낮은 음역을 낸다\", \"parts\": [], \"songs\": [], \"tasks\": [], \"ranges\": [{\"blow\": \"HIGH\", \"label\": \"역취 · 높은 단\", \"firstPitch\": \"淋\", \"description\": \"입김을 세게 불어 한 옥타브 올려요.\"}, {\"blow\": \"LOW\", \"label\": \"저취 · 낮은 단\", \"firstPitch\": \"㑣\", \"description\": \"입김을 느슨하게 해 한 옥타브 내려요.\"}], \"source\": \"단소 지도서 발음법 4·5항, 대금 교실 5~7차시, 대금 기초편 10~13차시, 소금 교실 13차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": {\"title\": \"새 음역의 음을 각각 2초 이상 유지\", \"description\": \"평취 음과 옥타브 차이가 나는지 봐요(예시).\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-02 06:46:25.286016');
INSERT INTO `lessons` (`id`, `track`, `seq`, `title`, `judge_type`, `is_optional`, `content_json`, `status`, `created_at`, `updated_at`) VALUES (25,'DAEGEUM_JEONGAK',7,'혀치기','BEAT',0,'{\"why\": \"같은 음을 여러 번 낼 때 숨은 그대로 두고 혀로 끊어요. 정간 안 박 나누기는 정간보 쉽게 읽기에서 봐요.\", \"goal\": \"같은 음을 혀로 끊어 반복한다\", \"parts\": [], \"songs\": [], \"tasks\": [{\"title\": \"혀치기\", \"description\": \"같은 음을 \\\"투·투·투\\\" 혀로 끊어 4번 반복해요.\"}], \"ranges\": [], \"source\": \"단소 지도서 발음법 6항, 소금 교실 8차시, 대금 기초편 14~18차시\", \"pitchNote\": null, \"pitchNames\": [], \"passCriteria\": {\"title\": \"혀치기 4번 반복, 박 어긋남 ±15% 이내\", \"description\": \"같은 음을 고르게 끊어 내는지 봐요(예시).\"}}','PUBLISHED','2026-11-02 06:46:25.286016','2026-11-10 05:33:39.772090');
